// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public { c = new Reentrance(); }

    // Fuzz params: depositor key and deposit amount
    function testFuzz_property(uint256 depositorKey, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        depositorKey = bound(depositorKey, 1, 115792089237316195423570985008687907852837564279074904382605163141518161494336);
        // keep amount in a sensible range but wide enough to find positive deposits
        amount = bound(amount, 0, 1 ether);
        address depositor = vm.addr(depositorKey);

        // ensure depositor has ETH to deposit
        vm.deal(depositor, amount);

        // If amount is zero, the property (sending exact positive balance) is vacuously about positive balances,
        // so allow the fuzzer to explore zero but it won't distinguish mutant; that's fine.

        // Make the depositor call addToBalance payable with 'amount'
        vm.prank(depositor);
        c.addToBalance{value: amount}();

        // Record depositor's balance as stored in contract
        uint256 stored = c.getBalance(depositor);

        // Now have depositor call withdrawBalance and observe whether they actually received the stored amount.
        // We cannot observe direct ETH transfer to an EOA easily; use a helper receiver that records received value.
        // Deploy a recording helper and impersonate it as the depositor by giving it the same address via creating
        // a wallet isn't possible; instead, we create a recorder contract and make the depositor address be its owner
        // by having the depositor forward the funds to the recorder and then call withdraw from the recorder via
        // a small attacker that will call c.withdrawBalance() from its own address.

        // Deploy a RecorderAttacker contract that will receive the withdrawal and record msg.value.
        RecorderAttacker attacker = new RecorderAttacker(c);

        // Fund the attacker so it can be the caller for withdraw (attackers need ETH to accept transfers if needed)
        vm.deal(address(attacker), 0);

        // Transfer the stored balance record in the contract to be associated to the attacker address.
        // We cannot change c.userBalance mapping directly; instead we must simulate depositing from the attacker address.
        // So first, ensure attacker has ETH to deposit equal to stored and call addToBalance from attacker.
        // Give attacker ETH equal to 'stored' (same as amount deposited earlier by depositor) so attacker can also have that balance.
        vm.deal(address(attacker), stored);
        vm.prank(address(attacker));
        c.addToBalance{value: stored}();

        // Now attacker calls withdrawBalance; the contract will call attacker (msg.sender) with the stored amount.
        attacker.callWithdraw();

        // The general rule: if stored > 0 then attacker.received() == stored. The mutant that sends 0 will violate this when stored > 0.
        uint256 received = attacker.receivedValue();

        // Single assertion: for the correct contract, for all inputs the recorded received value equals the stored balance
        // (this will hold even for stored==0). The mutant that sends 0 will make this fail for stored>0.
        assertTrue(received == stored);
    }
}

// Helper that calls withdrawBalance on c and records the msg.value it receives
contract RecorderAttacker {
    Reentrance immutable c;
    uint256 public lastReceived;

    constructor(Reentrance _c) {
        c = _c;
    }

    // expose a function to call withdrawBalance from this contract
    function callWithdraw() public {
        c.withdrawBalance();
    }

    // record any ETH received
    receive() external payable {
        lastReceived += msg.value;
    }

    function receivedValue() external view returns (uint256) {
        return lastReceived;
    }
}
